  var gd=new THREE.Mesh(new THREE.PlaneGeometry(1,1).rotateX(-Math.PI/2),new THREE.MeshBasicMaterial(add({map:glowTex(i?'rgba(255,170,60,.6)':'rgba(96,165,250,.5)','rgba(0,0,0,0)'),opacity:0})));gd.scale.setScalar(6);scene.add(gd);
