 // ai4：表情只跟真實活動類型走：聊天/語音→說話；學習中/考試中/讀書/審核計畫→思考；考試通過→開心；有活動但 2 分鐘沒新動作→想睡
 function mood(w){var a=String(w&&w.activity||''),age=w&&w.last_at?Date.now()-Date.parse(w.last_at):1e9;if(/考試通過/.test(a))return'happy';if(/聊天|語音/.test(a)&&age<60e3)return'talk';if(/學習中|考試中/.test(a)&&age<4*60e3)return'think';if(age>120e3)return'sleepy';if(/讀書|審核|考完|看圖|做圖|影片|3D/.test(a))return'think';return'idle'}
 function face(o,t){var c=o.fc,x=c.getContext('2d'),m=mood(o.row),W=256;x.clearRect(0,0,W,W);var dk=!o.i,eye=dk?'#7dd3fc':'#4a2306',gl=dk?'#38bdf8':null;
  if(t>o.nb){o.bk=t;o.nb=t+2+Math.random()*4}var bl=t-o.bk<.14,lx=Math.sin(t*.7+o.i)*10+(Math.sin(t*.23)>.6?14:0),ly=m==='think'?-14:m==='sleepy'?6:Math.sin(t*.5)*4;
  x.save();if(gl){x.shadowColor=gl;x.shadowBlur=24}x.fillStyle=eye;x.strokeStyle=eye;x.lineWidth=9;x.lineCap='round';
  [-1,1].forEach(function(s){var ex=128+s*44,ey=108;if(bl||m==='happy'){x.beginPath();if(m==='happy')x.arc(ex,ey+8,20,Math.PI*1.15,Math.PI*1.85);else{x.moveTo(ex-18,ey);x.lineTo(ex+18,ey)}x.stroke();return}
   var h=m==='sleepy'?9:24;x.beginPath();x.ellipse(ex+lx*.3,ey+ly*.3,dk?16:15,h,0,0,7);x.fill();if(!dk){x.fillStyle='#fff';x.beginPath();x.arc(ex+lx*.5-4,ey+ly*.5-7,5,0,7);x.fill();x.fillStyle=eye}});
  if(!dk){x.fillStyle='rgba(255,110,110,.45)';[-1,1].forEach(function(s){x.beginPath();x.ellipse(128+s*74,150,18,10,0,0,7);x.fill()});x.fillStyle=eye}
  x.beginPath();if(m==='talk'){var op=6+Math.abs(Math.sin(t*11))*16;x.ellipse(128,170,18,op,0,0,7);x.fill()}else if(m==='happy'){x.arc(128,160,26,.15*Math.PI,.85*Math.PI);x.stroke()}else if(m==='think'){x.moveTo(110,172);x.lineTo(146,166);x.stroke();x.font='bold 40px sans-serif';x.fillText('…'.slice(0,1),180,70+Math.sin(t*3)*4)}else if(m==='sleepy'){x.ellipse(128,170,8,6,0,0,7);x.fill();x.font='bold 34px sans-serif';x.fillText('z',190,70-((t*20)%30))}else{x.arc(128,158,16,.2*Math.PI,.8*Math.PI);x.stroke()}
  x.restore();o.ft.needsUpdate=true}
 function ago(t){var s=Math.round((Date.now()-Date.parse(t))/1000);return s<60?s+' 秒前':Math.round(s/60)+' 分鐘前'}
 async function pull(){try{var d=MOCK?(Q0.get('orbs')==='1'?{rows:[{id:'darkstar',name:'暗星（測試心跳）',activity:'聊天',last_at:new Date().toISOString()},{id:'dawn-light',name:'曙光（測試心跳）',activity:'做圖',last_at:new Date().toISOString()}]}:{rows:[]}):await api('degree','ai_presence',{});ROWS=d.rows||[]}catch(_){}
  ROWS.forEach(function(r){var o=OR[r.id]||build(r.id);o.row=r;var on=r.last_at&&Date.now()-Date.parse(r.last_at)<FRESH;o.g.visible=on;o.gd.visible=on;if(!on)o.L.intensity=0});cnt(1)}
 var SPD=null,SPN=['國小','國中','高中','大學','碩士','博士'];async function spPull(){try{SPD=await api('degree','special_public',{})}catch(_){}}spPull();setInterval(spPull,120000);
 function spDeg(id){var g=SPD&&(SPD.degree||[]).find(function(x){return x.agent_id===id});return g&&g.tier?SPN[g.tier-1]+' '+g.level+' 級':null}
 function spLine(id){var g=spDeg(id),n=SPD?(SPD.learning||[]).filter(function(x){return x.agent_id===id}).length:0;return '<p>🎓 學歷：<b>'+(g||'未鑑定')+'</b>（和協作池同一套考題、同樣評分；用它自己真正的模型路徑作答）'+(n?'<br>📚 最近真實學習 '+n+' 筆':'')+'</p>'}
 setTimeout(function(){var c=$('cDeg');if(c)c.addEventListener('click',function(){setTimeout(function(){var sh=$('sheet');if(!sh||!sh.classList.contains('on')||!/學歷分佈/.test(sh.innerHTML))return;var d=document.createElement('div');d.innerHTML='<h4>✨ 特別成員（另列，不算進上面的分佈）</h4><p>🌑 暗星：<b>'+(spDeg('darkstar')||'未鑑定')+'</b>　🌅 曙光：<b>'+(spDeg('dawn-light')||'未鑑定')+'</b></p><p class="muted">走暗星／曙光自己真正的路徑閉卷作答；呼叫失敗的不記錄。</p>';sh.appendChild(d)},60)})},3000);
 // ai5：暗星／曙光真的在城裡時，💤 待命（即時計算的數字）各 +1；離開就扣回。只改即時數字，不寫死。
 var CW='',BASE='';function cnt(force){var c=$('cIdle');if(!c)return;var t=c.textContent;if(t!==CW)BASE=t;else if(!force)return;var P=Object.keys(OR).filter(function(k){return OR[k].g.visible}).length;CW=P?BASE.replace(/(待命 )(\d+)/,function(_,a,n){return a+(+n+P)})+'（含✨'+P+'）':BASE;if(c.textContent!==CW)c.textContent=CW}
